local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["af06df4ab7fd00f0"] = { "In tanti lunghi anni ho imparato molto sulle pozioni, {name}, e quel sapere è a tua disposizione. Non devi far altro che chiedere.", "." },
  ["af07c3ff5be1f780"] = { "Il Maestro nutre un grande interesse per la tana di Nefarian. Se solo qualcuno sconfiggesse il drago e i suoi servitori e raccontasse la storia al principe! Scommetto che al principe si scioglierebbe la lingua. Brandicenere potrebbe essere ritrovata!", "." },
  ["af0df44a689ba99c"] = { "Ho un'idea abbastanza precisa di cosa farà il vecchio Greatfather Winter quando finirà questo turno. Ho una bottiglia di spirito del Grande Inverno proprio qui nella borsa, e intendo vederne il fondo.", "." },
  ["af1147da124e6ee9"] = { "I non morti strisciano per tutta la regione. Dov'è l'esercito di ⟦Stormwind=Roccavento⟧?", "." },
  ["af165695390c7bbf"] = { "Per favore, apri la porta del cortile.", "." },
  ["af16c52cfbee8f0a"] = { "Da 10.000 anni governo questo regno. In questo tempo ho udito molti racconti affascinanti da coloro che hanno percorso il suolo sacro della House of Shen'dralar.\n\nPoiché non posso lasciare questo luogo, scambio spesso storie con i visitatori. Hai una storia per me, o forse preferisci ascoltarne una?", "." },
  ["af19903bd4cfd760"] = { "I nemici hanno raggiunto la porta! Avanti! Dobbiamo resistere!", "." },
  ["af1b87683a5b66eb"] = { "Spero per te che sia una cosa importante....", "." },
  ["af1d5c49ef31d920"] = { "Fammi vedere cosa sai fare, <novellino/novellina>!", "." },
  ["af25aa47f717a571"] = { "La tua non morte non è la fine della tua vita, ma l'inizio. Ora sta a te decidere dove ti porterà il tuo destino.", "." },
  ["af31fb4487ed71a9"] = { "%s prende di nuovo la mira...", "." },
  ["af32dc07bd1206df"] = { "COCCODÈ! I sensori rilevano un'anomalia spaziale: pericolo imminente! COCCODÈ!", "." },
  ["af3a728d034faf2b"] = { "Le mie ⟦Zandalar Demoniac's Wraps=Polsiere Demoniache degli Zandalari⟧ sono sparite. Puoi darmene un altro paio?", "." },
  ["af3f7d9ed4537301"] = { "Con il tuo aiuto posso esaminare queste gallerie.", "." },
  ["af40863798ea55e9"] = { "Che Elune sia con noi! Allontaniamoci in fretta da questa fortezza malvagia.", "." },
  ["af48955a76e2f28b"] = { "Merideth, potrei avere ancora un po' di Biada Ricostituente Arricchita, per favore?", "." },
  ["af4a3af9873348a8"] = { "Noi avere un occhio e vedere meglio di te! Banca in centro di ⟦Undercity=Sepulcra⟧!", "." },
  ["af5555639fc1f14f"] = { "Bella domanda, {race}. In gioventù non avevo legami né pensieri al mondo. A quei tempi cantavo in un quartetto vocale di ⟦Stormwind=Roccavento⟧ chiamato Four Dons. È lì che ho imparato a confezionare la tenuta della Falce Ossuta.", "." },
  ["af5698bbda9c05eb"] = { "La temperatura è... non abbastanza alta!", "." },
  ["af582cf3d1e39164"] = { "Carne, pelle, ossa... un buon cacciatore non spreca nulla. Ogni brandello di cuoio si può recuperare, magari per rinforzare l'armatura di un alleato. Così ognuno di noi è forte da solo, ma insieme diventiamo invincibili.", "." },
  ["af5d605006c678e5"] = { "Questa luce blu... È strana, {name}. Secondo te cosa significa?", "." },
  ["af676d087f665fe4"] = { "Salute, {name}! <Benvenuto/Benvenuta> nel mio umile giardino. Il tempo è stato perfetto, ultimamente. Speriamo che regga fino a un raccolto abbondante.", "." },
  ["af685c9ac42316e8"] = { "Noi orchi di solito siamo riservati, ma ultimamente nessuno nasconde i propri sentimenti.", "." },
  ["af69a1e2b6828af6"] = { "Possa la tua abilità nel fondere il Ferroscuro servirti bene, {name}. Ma non lasciare che il tuo sapere ti corrompa... come ha corrotto noi.", "." },
  ["af71d25d88e961f0"] = { "Ho bisogno di addestramento, Lumak.", "." },
  ["af7531b98d4feb3d"] = { "Ah, è da tanto tempo che non vieni a trovarmi, {name}. Cosa posso fare per te oggi? Hai l'aria di chi ha visto da poco la battaglia in faccia. Bene... bene per l'⟦Horde=Orda⟧ e bene per te. Più battaglie vedi, più sarai utile; e anche più forte.", "." },
  ["af87c8692faf65e7"] = { "Chi osa intromettersi nel clan ⟦Blackrock=Roccianera⟧? Morte a te, {race}!", "." },
  ["afae813357def975"] = { "Panini, focaccine e pane. Appena sfornati!", "." },
  ["afb71b417c494309"] = { "Adesso mi ci vorrebbe proprio un bacio. Sai dove posso trovarne uno?", "." },
  ["afbcc8845c745012"] = { "Non c'è di che! Devo rimettermi in cammino... state attenti, tutti quanti.", "." },
  ["afbf809c23e03b6b"] = { "In cambio di un ⟦Sulfuron Ingot=Lingotto di Sulfuron⟧ ho l'autorizzazione a concederti una copia dei progetti per forgiare un Martello di Sulfuron.\n\nOra, chi è avventuroso come te starà probabilmente pensando: \"A che mi servirebbe mai un martello così, quando quello che ho già è di gran lunga superiore?\"\n\nBe', lascia che ti dica una cosa, <bello/bella>: non c'è niente di più superiore di ciò che può diventare il Martello di Sulfuron!", "." },
  ["afc6232e03eb7e57"] = { "%s scrolla le spalle.", "." },
  ["afcd3a9e3132d1a3"] = { "La scuola di negromanzia nota come Scholomance si trova sull'isola in rovina di Caer Darrow, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "." },
  ["afd035ed7f1342cf"] = { "Dovresti cercare Bronk allo ⟦Steelgrill's Depot=Scalo di Grigliafredda⟧. Quando non armeggia con qualche strano congegno, di solito chiacchiera con i piloti dei loro carri a vapore.", "." },
  ["afd7f15dd04a64fe"] = { "Sei gentile a chiedere, {class}, ma abbiamo tutto il Cuoio Leggero che ci serve. Magari a qualcun altro degli incaricati della raccolta qui intorno serve il tuo aiuto?", "." },
  ["afe2a716f6f7f735"] = { "Vorrei addestrarmi.", "." },
  ["afea0e83ddbcf9f7"] = { "Un difensore è caduto!", "." },
  ["aff21142e68ee17a"] = { "Attenzione! Siamo sotto attacco!", "." },
  ["aff619fcbea50f3e"] = { "Dovresti parlare con Winstone. Ho sentito che cerca ladri con la tua abilità.", "." },
})
